package com.lovelyshades.entity;
import jakarta.persistence.*;import jakarta.validation.constraints.*;import java.math.*;
@Entity @Table(name="producto")
public class Producto { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="id_producto") private Long idProducto; @NotBlank @Column(name="nombre",nullable=false,length=120) private String nombre; @Column(name="descripcion",length=255) private String descripcion; @NotNull @DecimalMin("0.0") @Column(name="precio",nullable=false,precision=12,scale=2) private BigDecimal precio; @Column(name="stock",nullable=false) private Integer stock=0; @Column(name="estado",nullable=false) private Boolean estado=true; public Long getIdProducto(){return idProducto;} public void setIdProducto(Long idProducto){this.idProducto=idProducto;} public String getNombre(){return nombre;} public void setNombre(String nombre){this.nombre=nombre;} public String getDescripcion(){return descripcion;} public void setDescripcion(String descripcion){this.descripcion=descripcion;} public BigDecimal getPrecio(){return precio;} public void setPrecio(BigDecimal precio){this.precio=precio;} public Integer getStock(){return stock;} public void setStock(Integer stock){this.stock=stock;} public Boolean getEstado(){return estado;} public void setEstado(Boolean estado){this.estado=estado;} }
